/* binary search; cps array is sorted ascending */
const uint16_t *cjk_glyph(uint32_t cp)
{
    unsigned lo = 0, hi = sizeof(cjk_cps) / sizeof(cjk_cps[0]);
    while (lo < hi) {
        unsigned mid = (lo + hi) / 2;
        if (cjk_cps[mid] == cp) return cjk_rows[mid];
        if (cjk_cps[mid] < cp) lo = mid + 1;
        else                   hi = mid;
    }
    return 0;
}
